sited.script:

const baseUrl = "https://nyaa.si";

function resolveUrl(u) {
    if (!u) return null;
    u = u.trim();
    if (u.startsWith("http://") || u.startsWith("https://") || u.startsWith("magnet:")) return u;
    if (u.startsWith("//")) return "https:" + u;
    if (u.startsWith("/")) return baseUrl + u;
    return baseUrl + "/" + u;
}

function cleanMagnet(mag) {
    if (!mag) return null;
    return mag.trim().replace(/&amp;/g, '&');
}

function extractImageUrl(text) {
    if (!text) return null;
    const m = text.match(/https?:\/\/[^\s"'<>)\]]+\.(?:jpg|jpeg|png|webp|gif)(?:\?[^\s"'<>)\]]*)?/i);
    return m ? m[0] : null;
}

function list_parse(url, html) {
    const $ = cheerio.load(html);
    let list = [];
    $('table.torrent-list tbody tr').each(function() {
        const $$ = cheerio.load($(this).html() || "");
        const tds = $$('td');
        if (tds.length < 6) return;

        const catLink = $$('a[href^="/?c="]').first();
        const category = catLink.attr('title') || "Nyaa";

        // 標題單元格內可能有留言數量 a.comments，因此取最後一個指向 /view/ 的連結
        let viewHref = null;
        let rawTitle = null;
        $$('a[href^="/view/"]').each(function() {
            const h = $$(this).attr('href') || "";
            if (h.indexOf("#comments") === -1) {
                viewHref = h;
                rawTitle = $$(this).attr('title') || $$(this).text().trim();
            }
        });

        const fileSize = tds.eq(3).text().trim();
        const seeders = tds.eq(5).text().trim();

        if (viewHref && rawTitle) {
            const metaPrefix = "[" + fileSize + (seeders ? " | ↑" + seeders : "") + "] ";
            list.push({
                group: category,
                name: gbk2big5.traditionalized(metaPrefix + rawTitle),
                url: resolveUrl(viewHref)
            });
        }
    });
    return JSON.stringify(list);
}

function book_parse(url, html) {
    const $ = cheerio.load(html);
    const title = $('h3.panel-title').first().text().trim() || "Nyaa Torrent";

    let author = "";
    let updateTime = "";
    let fileSize = "";
    let seeders = "";
    let completed = "";

    $('div.panel-body div.row').each(function() {
        const $$ = cheerio.load($(this).html() || "");
        const cols = $$('div');
        for (let i = 0; i < cols.length - 1; i++) {
            const label = cols.eq(i).text().trim();
            const val = cols.eq(i + 1).text().trim();
            if (label === "Submitter:") author = val;
            else if (label === "Date:") updateTime = val;
            else if (label === "File size:") fileSize = val;
            else if (label === "Seeders:") seeders = val;
            else if (label === "Completed:") completed = val;
        }
    });

    const descRaw = $('#torrent-description').text() || "";
    let logo = extractImageUrl(descRaw);
    if (!logo) {
        $('#torrent-description img').each(function() {
            if (!logo) {
                const s = $(this).attr('src');
                if (s) logo = resolveUrl(s);
            }
        });
    }

    const statsLine = [
        fileSize ? "大小: " + fileSize : "",
        seeders ? "做種(S): " + seeders : "",
        completed ? "完成: " + completed : ""
    ].filter(Boolean).join(" | ");

    const introText = (statsLine ? statsLine + "\n" : "") + descRaw.trim().substring(0, 600);

    let primaryMagnet = null;
    $('a[href^="magnet:"]').each(function() {
        if (!primaryMagnet) {
            primaryMagnet = cleanMagnet($(this).attr('href'));
        }
    });

    let sections = [];
    if (primaryMagnet) {
        sections.push({
            group: "磁力串流 (邊下邊播)",
            name: gbk2big5.traditionalized(title),
            url: primaryMagnet
        });
    }

    $('div.torrent-file-list li').each(function() {
        const fileText = $(this).text().trim();
        const lower = fileText.toLowerCase();
        if (fileText && (lower.includes('.mp4') || lower.includes('.mkv') || lower.includes('.avi') || lower.includes('.webm')) && primaryMagnet) {
            if (sections.length < 40) {
                sections.push({
                    group: "種子內含影片",
                    name: gbk2big5.traditionalized(fileText),
                    url: primaryMagnet
                });
            }
        }
    });

    return JSON.stringify({
        name: gbk2big5.traditionalized(title),
        author: author,
        updateTime: updateTime,
        logo: logo,
        intro: gbk2big5.traditionalized(introText),
        sections: sections
    });
}

function section_parse(url, html) {
    if (url && url.indexOf("magnet:") === 0) {
        return JSON.stringify({
            type: "video",
            data: cleanMagnet(url)
        });
    }
    if (html) {
        const $ = cheerio.load(html);
        const mag = $('a[href^="magnet:"]').first().attr('href');
        if (mag) {
            return JSON.stringify({
                type: "video",
                data: cleanMagnet(mag)
            });
        }
    }
    return JSON.stringify({
        type: "webview",
        data: url
    });
}
